def is_multiply_prime(a):
    def get_factors(n):
        factors = []
        d = 2
        while d * d <= n:
            while n % d == 0:
                factors.append(d)
                n //= d
            d += 1 if d == 2 else 2
        if n > 1:
            factors.append(n)
        return factors

    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    prime_factors = get_factors(a)

    # Check how many distinct prime factors there are and their count
    unique_primes = []
    for p in set(prime_factors):
        if is_prime(p):
            unique_primes.append(p)

    total_count = sum([prime_factors.count(p) for p in unique_primes])

