                    count += 1
                    n //= d
                factors.append((d, count))
            elif d > 2 and d % 2 != 0:
                d += 2
        if n > 1:
            factors.append((n, 1))
        return factors

    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

